mapper.select:
SELECT id
FROM stock_effect
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND source_service=#{sourceService}
AND action=#{action}
AND fact_type=#{factType}
AND fact_parent_id=#{factParentId}
AND fact_part_id=#{factPartId}
AND fact_line_id=#{factLineId}

SELECT id, action, fact_type, fact_parent_id, fact_part_id, fact_line_id, business_effect_key, active_command_id, applied_command_id, attempt_no, state, version
FROM stock_effect
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND id=#{effectId} FOR UPDATE

SELECT id, action, fact_type, fact_parent_id, fact_part_id, fact_line_id, business_effect_key, active_command_id, applied_command_id, attempt_no, state, version
FROM stock_effect
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND id=#{effectId}

mapper.update:
UPDATE stock_effect
SET attempt_no=#{attemptNo}, active_command_id=#{commandId}, state=#{state}, version=version+1, updated_at=#{now}
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND id=#{effectId}
AND version=#{expectedVersion}
AND applied_command_id IS NULL
AND state=#{fromState}

UPDATE stock_effect
SET active_command_id=#{commandId}, attempt_no=GREATEST(attempt_no, #{attemptNo}), state=#{state}, version=version+1, updated_at=#{now}
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND id=#{effectId}
AND applied_command_id IS NULL
AND (active_command_id IS NULL OR active_command_id=#{commandId})

UPDATE stock_effect
SET applied_command_id=#{commandId}, state='APPLIED', version=version+1, updated_at=#{now}
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND id=#{effectId}
AND applied_command_id IS NULL
AND active_command_id=#{commandId}

UPDATE stock_effect
SET active_command_id=#{commandId}, attempt_no=GREATEST(attempt_no, 1), state=#{state}, version=version+1, updated_at=#{now}
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND id=#{effectId}
AND applied_command_id IS NULL
AND (active_command_id=#{commandId} OR active_command_id IS NULL)

UPDATE stock_effect
SET active_command_id=#{commandId}, state='SAFE_CLOSED', version=version+1, updated_at=#{now}
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND id=#{effectId}
AND applied_command_id IS NULL
AND state NOT IN ('STARTED','UNKNOWN','APPLIED')

mapper.select:
SELECT intent_digest, digest_version, canonical_request, state
FROM stock_effect_attempt
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND effect_id=#{effectId}
AND attempt_no=#{attemptNo}

SELECT request_digest, resource_id
FROM write_idempotency
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND client_operation_id=#{clientOperationId}
